const copy: Record<Locale, Record<string, SpeciesCopy>> = {
  en: { ...en, ...pack.en },
  ru: { ...ru, ...pack.ru },
  pl: { ...pl, ...pack.pl },
  lv: { ...lv, ...pack.lv },
};

export function getWildlifeSpecies(locale: Locale): Species[] {
  return speciesMeta.map((meta) => {
    const fields = copy[locale][meta.slug] ?? copy.en[meta.slug];
    return { ...meta, ...fields };
  });
}

export function getWildlifeByStatus(
  locale: Locale,
  status: WildlifeStatus,
): Species[] {
  return getWildlifeSpecies(locale).filter((item) => item.status === status);
}

export function getWildlifeBySlug(
  locale: Locale,
  slug: string,
): Species | undefined {
  const meta = getSpeciesMeta(slug);
  if (!meta) return undefined;
  const fields = copy[locale][slug] ?? copy.en[slug];
  if (!fields) return undefined;
  return { ...meta, ...fields };
}
